{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Isradipine, a highly lipophilic dihydropyridine with extensive first-pass metabolism, has systemic availability of only about 16.5% in healthy volunteers; this high-transfer record directly supports a low F prediction for the query, which is even larger and more lipophilic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nifedipine reaches about 45% oral bioavailability in healthy volunteers despite being a poorly soluble CYP3A4 substrate, providing contradictory evidence for high F; however, its much lower molecular weight and less extreme lipophilicity make it a weaker anchor for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "A pyrazolopyrimidinone analogue shows 34% oral bioavailability in healthy volunteers, but its smaller size and polar sulfonyl-piperazine substituents make it poorly representative of the query's large isoprenoid quinone; this contradictory evidence carries low weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a very large, highly lipophilic isoprenoid quinone with negligible aqueous solubility. High-transfer evidence from isradipine showing ~17% F supports low bioavailability, while moderate-F records from smaller, more soluble drugs are less applicable. Overall F is more likely below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule or a close structural analogue.",
    "Absolute F for CoQ10-like compounds is confounded by endogenous synthesis and lack of a conventional IV reference.",
    "Formulation and fed/fasted effects are not captured in the available evidence records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

